        </div>

        <svg id="pcSvg" role="img" aria-label="Parallel coordinates plot of seven national development indicators"></svg>

        <div class="controls" aria-label="Chart controls">
          <div class="control">
            <label for="axisScale">Axis scaling</label>
            <select id="axisScale" onchange="setScaling(this.value)">
              <option value="z" selected>Z-score (within axis)</option>
              <option value="minmax">Min–max (within axis)</option>
              <option value="raw">Raw values</option>
            </select>
          </div>
          <div class="control">
            <label for="highlightGroup">Highlight</label>
            <select id="highlightGroup" onchange="setHighlight(this.value)">
              <option value="All" selected>All income groups</option>
              <option value="High">High</option>
              <option value="Upper-Middle">Upper-Middle</option>
              <option value="Lower-Middle">Lower-Middle</option>
              <option value="Low">Low</option>
            </select>
          </div>
        </div>

        <p class="note">
          Data: approximate 2023 estimates from World Bank/UNDP/Freedom House/Transparency International/IEA/SIPRI/ITU (see dataset notes).
        </p>
      </section>
    </section>
  </main>

  </main>

  <div class="tooltip" id="tooltip" role="dialog" aria-label="Country details"></div>

  <script>
    function toggleMenu() {
      var dropdown = document.getElementById('vizMenuDropdown') || document.getElementById('vizMenu');
      if (dropdown) dropdown.classList.toggle('open');
    }
    document.addEventListener('click', function(e) {
      if (!e.target.closest('.viz-menu')) {
        var dropdown = document.getElementById('vizMenuDropdown') || document.getElementById('vizMenu');
        if (dropdown) dropdown.classList.remove('open');
      }
    });
    document.addEventListener('keydown', function(e) {
      if (e.key === 'Escape') {
        var dropdown = document.getElementById('vizMenuDropdown') || document.getElementById('vizMenu');
        if (dropdown) dropdown.classList.remove('open');
      }
    });

    var savedTheme = localStorage.getItem('viz-theme');
    var currentTheme = savedTheme || (window.matchMedia('(prefers-color-scheme: light)').matches ? 'light' : 'dark');
    function applyTheme(t) {
      document.documentElement.className = 'theme-' + t;
      document.getElementById('themeIcon').textContent = t === 'dark' ? '🌙' : '☀️';
      document.getElementById('themeLabel').textContent = t === 'dark' ? 'Dark' : 'Light';
      localStorage.setItem('viz-theme', t);
      currentTheme = t;
      if (typeof onThemeChange === 'function') onThemeChange();
    }
    function cycleTheme() { applyTheme(currentTheme === 'dark' ? 'light' : 'dark'); }
    applyTheme(currentTheme);

    async function downloadImage() {
      var menu = document.querySelector('.viz-menu');
      menu.style.display = 'none';
      try {
        var url = await htmlToImage.toPng(document.body, {
          quality: 1,
          pixelRatio: 2,
          filter: function(n) { return !n.classList || !n.classList.contains('viz-menu'); }
        });
        var a = document.createElement('a');
        a.href = url;
        a.download = document.title.replace(/\s+/g, '-').toLowerCase() + '.png';
        a.click();
      } catch(e) {
        console.error('Download failed:', e);
      }
      menu.style.display = '';
    }

    var incomeColors = {
      'High': '#60a5fa',
      'Upper-Middle': '#34d399',
      'Lower-Middle': '#f59e0b',
      'Low': '#f87171'
    };

    var dimensions = [
      { key: 'gdp_per_capita_usd', label: 'GDP per capita', unit: 'USD', fmt: function(v){ return '$' + Math.round(v).toLocaleString(); } },
      { key: 'hdi', label: 'HDI', unit: 'index', fmt: function(v){ return v.toFixed(3); } },
      { key: 'freedom_index', label: 'Freedom Index', unit: 'score (0–100)', fmt: function(v){ return Math.round(v).toString(); } },
      { key: 'corruption_perceptions_index', label: 'Corruption Perceptions', unit: 'CPI (0–100)', fmt: function(v){ return Math.round(v).toString(); } },
      { key: 'co2_emissions_per_capita_tons', label: 'CO₂ per capita', unit: 'tons', fmt: function(v){ return v.toFixed(1) + ' t'; } },
      { key: 'military_expenditure_pct_gdp', label: 'Military exp.', unit: '% GDP', fmt: function(v){ return v.toFixed(1) + '%'; } },
      { key: 'internet_penetration_pct', label: 'Internet use', unit: '%', fmt: function(v){ return Math.round(v) + '%'; } }
    ];

    var state = {
      scaling: 'z',
      highlight: 'All',
      data: []
    };

    function setScaling(v) {
      state.scaling = v;
      render();
    }
    function setHighlight(v) {
      state.highlight = v;
      render();
    }

    function isDark() { return document.documentElement.classList.contains('theme-dark'); }

    function computeStats(values) {
      var n = values.length;
      var mean = values.reduce(function(a,b){ return a+b; },0) / n;
      var variance = values.reduce(function(a,b){ var d=b-mean; return a + d*d; },0) / (n || 1);
      var sd = Math.sqrt(variance) || 1;
      var min = Math.min.apply(null, values);
      var max = Math.max.apply(null, values);
      return { mean: mean, sd: sd, min: min, max: max };
    }

    function normalize(value, stats, mode) {
      if (mode === 'raw') return value;
      if (mode === 'minmax') {
        var d = (stats.max - stats.min) || 1;
        return (value - stats.min) / d;
      }
      // z-score
      return (value - stats.mean) / stats.sd;
    }

    function buildLegend() {
      var legendRow = document.getElementById('legendRow');
      legendRow.innerHTML = '';
      ['High','Upper-Middle','Lower-Middle','Low'].forEach(function(g){
        var pill = document.createElement('div');
        pill.className = 'pill';
        var sw = document.createElement('span');
        sw.className = 'swatch';
        sw.style.background = incomeColors[g];
        var tx = document.createElement('span');
        tx.textContent = g;
        pill.appendChild(sw);
        pill.appendChild(tx);
        legendRow.appendChild(pill);
      });
    }

    function formatTick(dimKey, val, mode, stats) {
      if (mode === 'raw') {
        var dim = dimensions.find(function(d){ return d.key === dimKey; });
        return dim ? dim.fmt(val) : String(val);
      }
      if (mode === 'minmax') {
        // show raw endpoints only
        return '';
      }
      // z
      return val.toFixed(1);
    }

    function computeCrossovers(data, dims) {
      // For each adjacent pair, compute Spearman correlation; report weakest correlation pair (most crossings)
      function rank(arr) {
        var sorted = arr.map(function(v,i){ return {v:v,i:i}; }).sort(function(a,b){ return a.v - b.v; });
        var r = new Array(arr.length);
        for (var j=0;j<sorted.length;j++) r[sorted[j].i] = j+1;
        return r;
      }
      function spearman(a,b) {
        var ra=rank(a), rb=rank(b);
        var n=a.length;
        var num=0, da=0, db=0;
        var ma = (n+1)/2;
        var mb = ma;
        for (var i=0;i<n;i++) {
          var xa=ra[i]-ma; var xb=rb[i]-mb;
          num += xa*xb;
          da += xa*xa;
          db += xb*xb;
        }
        var den = Math.sqrt(da*db) || 1;
        return num/den;
      }
      var best = {pair: null, rho: 1};
      for (var k=0;k<dims.length-1;k++) {
        var d1=dims[k].key, d2=dims[k+1].key;
        var a=data.map(function(r){ return r[d1]; });
        var b=data.map(function(r){ return r[d2]; });
        var rho = spearman(a,b);
        if (Math.abs(rho) < Math.abs(best.rho)) best = {pair: [dims[k].label, dims[k+1].label], rho: rho};
      }
      return best;
    }

    function render() {
      if (!window.d3) { console.error('D3 not loaded'); return; }

      var svg = d3.select('#pcSvg');
      svg.selectAll('*').remove();

      var bb = document.getElementById('pcSvg').getBoundingClientRect();
      var width = Math.max(900, Math.round(bb.width));
      var height = Math.round(bb.height);
      svg.attr('viewBox', '0 0 ' + width + ' ' + height);

      var margin = { top: 44, right: 40, bottom: 34, left: 40 };
      var innerW = width - margin.left - margin.right;
      var innerH = height - margin.top - margin.bottom;

      var g = svg.append('g').attr('transform', 'translate(' + margin.left + ',' + margin.top + ')');

      var mode = state.scaling;
      var data = state.data.slice();

      // Stats per dimension
      var stats = {};
      dimensions.forEach(function(dim){
        stats[dim.key] = computeStats(data.map(function(d){ return +d[dim.key]; }));
      });

      // y scales
      var y = {};
      dimensions.forEach(function(dim) {
        if (mode === 'raw') {
          var s = stats[dim.key];
          y[dim.key] = d3.scaleLinear().domain([s.min, s.max]).range([innerH, 0]).nice();
        } else if (mode === 'minmax') {
          y[dim.key] = d3.scaleLinear().domain([0, 1]).range([innerH, 0]);
        } else {
          // z-score domain: clamp to [-3,3] based on observed
          var zs = data.map(function(d){ return normalize(+d[dim.key], stats[dim.key], 'z'); });
          var zmin = Math.min.apply(null, zs);
          var zmax = Math.max.apply(null, zs);
          var pad = 0.15;
          y[dim.key] = d3.scaleLinear().domain([zmin - pad, zmax + pad]).range([innerH, 0]).nice();
        }
      });

      var x = d3.scalePoint().domain(dimensions.map(function(d){ return d.key; })).range([0, innerW]).padding(0.5);

      function valueFor(d, key) {
        var v = +d[key];
        if (mode === 'raw') return v;
        if (mode === 'minmax') return normalize(v, stats[key], 'minmax');
        return normalize(v, stats[key], 'z');
      }

      function path(d) {
        return d3.line()(dimensions.map(function(p) { return [x(p.key), y[p.key](valueFor(d, p.key))]; }));
      }

      // Grid/axes
      var axisG = g.selectAll('.axis').data(dimensions).enter().append('g')
        .attr('class', 'axis')
        .attr('transform', function(d) { return 'translate(' + x(d.key) + ',0)'; });

      axisG.each(function(dim) {
        var ax;
        if (mode === 'minmax') {
          ax = d3.axisLeft(y[dim.key]).ticks(5);
        } else {
          ax = d3.axisLeft(y[dim.key]).ticks(5);
        }
        d3.select(this).call(ax);
      });

      // Axis labels + units
      axisG.append('text')
        .attr('class', 'axis-label')
        .attr('text-anchor', 'middle')
        .attr('y', -18)
        .text(function(d) { return dimensions.find(function(xd){ return xd.key===d.key; }).label; });

      axisG.append('text')
        .attr('text-anchor', 'middle')
        .attr('y', -2)
        .attr('fill', 'var(--text-secondary)')
        .attr('font-size', 10)
        .text(function(d) {
          var dim = dimensions.find(function(xd){ return xd.key===d.key; });
          return mode === 'raw' ? dim.unit : (mode === 'minmax' ? '0–1' : 'z');
        });

      // Overlay subtle band to help track crossings
      g.append('rect')
        .attr('x', 0)
        .attr('y', 0)
        .attr('width', innerW)
        .attr('height', innerH)
        .attr('fill', 'transparent');

      // Lines
      var highlightGroup = state.highlight;
      var showAll = highlightGroup === 'All';

      var lines = g.append('g').attr('aria-label', 'Country polylines');

      var tooltip = document.getElementById('tooltip');

      function showTooltip(ev, d) {
        var linesHtml = '';
        dimensions.forEach(function(dim) {
          linesHtml += '<div class="k">' + dim.label + '</div><div class="v">' + (dim.fmt(+d[dim.key])) + '</div>';
        });
        tooltip.innerHTML =
          '<div class="t-title">' + d.country + '</div>' +
          '<div class="t-sub">Income group: <span style="color:' + incomeColors[d.income_group] + '">' + d.income_group + '</span></div>' +
          '<div class="t-grid">' + linesHtml + '</div>';
        tooltip.style.opacity = '1';
        tooltip.style.transform = 'translateY(0)';
        positionTooltip(ev);
      }

      function positionTooltip(ev) {
        var pad = 14;
        var x = ev.clientX + pad;
        var y = ev.clientY + pad;
        var rect = tooltip.getBoundingClientRect();
        if (x + rect.width + pad > window.innerWidth) x = ev.clientX - rect.width - pad;
        if (y + rect.height + pad > window.innerHeight) y = ev.clientY - rect.height - pad;
        tooltip.style.left = Math.max(10, x) + 'px';
        tooltip.style.top = Math.max(10, y) + 'px';
      }

      function hideTooltip() {
        tooltip.style.opacity = '0';
        tooltip.style.transform = 'translateY(-2px)';
      }

      var lineSel = lines.selectAll('path')
        .data(data)
        .enter()
        .append('path')
        .attr('class', 'line')
        .attr('d', path)
        .attr('stroke', function(d) { return incomeColors[d.income_group] || '#94a3b8'; })
        .attr('tabindex', 0)
        .attr('role', 'img')
        .attr('aria-label', function(d){ return 'Country profile: ' + d.country + ', income group ' + d.income_group; })
        .on('mouseenter', function(ev, d) {
          lineSel.classed('dim', true).classed('highlight', false);
          d3.select(this).classed('dim', false).classed('highlight', true);
          showTooltip(ev, d);
        })
        .on('mousemove', function(ev) { positionTooltip(ev); })
        .on('mouseleave', function() {
          hideTooltip();
          applyHighlight();
        })
        .on('focus', function(ev, d) {
          lineSel.classed('dim', true).classed('highlight', false);
          d3.select(this).classed('dim', false).classed('highlight', true);
          showTooltip(ev, d);
        })
        .on('blur', function() {
          hideTooltip();
          applyHighlight();
        });

      function applyHighlight() {
        if (showAll) {
          lineSel.classed('dim', false).classed('highlight', false);
          lineSel.style('opacity', 0.28);
          return;
        }
        lineSel.classed('highlight', false);
        lineSel.classed('dim', function(d){ return d.income_group !== highlightGroup; });
        lineSel.style('opacity', function(d){ return d.income_group === highlightGroup ? 0.52 : null; });
      }

      applyHighlight();

      // Crossovers summary
      var cross = computeCrossovers(state.data, dimensions);
      var txt = 'Strongest crossings (weakest rank alignment): ' + cross.pair[0] + ' → ' + cross.pair[1] + ' (Spearman ρ ≈ ' + cross.rho.toFixed(2) + ')';
      document.getElementById('crossingsText').textContent = txt;

      // Extra: emphasize Freedom↔Corruption pairing per goal
      var freedomIdx = dimensions.findIndex(function(d){ return d.key === 'freedom_index'; });
      var cpiIdx = dimensions.findIndex(function(d){ return d.key === 'corruption_perceptions_index'; });
      if (freedomIdx >=0 && cpiIdx === freedomIdx+1) {
        var fx = x('freedom_index');
        var cx = x('corruption_perceptions_index');
        g.append('rect')
          .attr('x', Math.min(fx,cx) - 24)
          .attr('y', -margin.top + 10)
          .attr('width', Math.abs(cx-fx) + 48)
          .attr('height', innerH + margin.top + 10)
          .attr('fill', isDark() ? 'rgba(59,130,246,0.06)' : 'rgba(37,99,235,0.06)')
          .attr('stroke', isDark() ? 'rgba(59,130,246,0.10)' : 'rgba(37,99,235,0.10)')
          .attr('stroke-width', 1)
          .lower();
      }

      // Foreground axis lines on top of highlight band
      axisG.raise();
      lines.raise();
    }

    function onThemeChange() {
      render();
    }

    async function loadData() {
      try {
        var res = await fetch('/app/benchmark/source_data.json');
        var json = await res.json();
        state.data = json.national_development.data;
        buildLegend();
        render();
      } catch(e) {
        console.error('Failed to load data:', e);
        document.getElementById('crossingsText').textContent = 'Failed to load data.';
      }
    }

    window.addEventListener('load', loadData);
  </script>
</body>
