      to { opacity: 1; transform: translateY(0); }
    }
    .animate { animation: fadeInUp 0.6s ease-out both; }
    .animate.delay-1 { animation-delay: 0.1s; }
    .animate.delay-2 { animation-delay: 0.2s; }

    @media (prefers-reduced-motion: reduce) {
      *, *::before, *::after { animation: none !important; transition: none !important; }
    }

    @media print {
      body { background: white !important; color: black !important; }
      .viz-menu { display: none !important; }
      * { print-color-adjust: exact; -webkit-print-color-adjust: exact; }
    }
    @page { margin: 1in; @bottom-center { content: "Page " counter(page); font-size: 9pt; color: #666; } }

    .viz-menu { position: fixed; top: 16px; right: 16px; z-index: 9999; }
    .viz-menu-toggle {
      width: 44px; height: 44px; border-radius: 12px;
      background: var(--surface); border: 1px solid var(--border);
      color: var(--text); cursor: pointer; display: flex;
      align-items: center; justify-content: center;
      backdrop-filter: blur(12px); transition: all 0.2s;
    }
    .viz-menu-toggle:hover { background: var(--surface-hover); }
    .viz-menu-dropdown {
      position: absolute; top: 52px; right: 0; min-width: 220px;
      background: var(--surface); border: 1px solid var(--border);
      border-radius: 12px; padding: 8px;
      opacity: 0; visibility: hidden; transform: translateY(-8px);
      transition: all 0.2s; backdrop-filter: blur(16px);
    }
    .viz-menu-dropdown.open { opacity: 1; visibility: visible; transform: translateY(0); }
    .viz-menu-dropdown button {
      width: 100%; padding: 10px 14px; border: none; border-radius: 8px;
      background: transparent; color: var(--text); font-size: 14px;
      font-family: inherit; cursor: pointer; text-align: left;
      display: flex; align-items: center; gap: 10px; transition: background 0.15s;
    }
    .viz-menu-dropdown button:hover { background: var(--surface-hover); }

    .skip-to-content {
      position: absolute; top: -40px; left: 6px; background: var(--accent);
      color: white; padding: 8px 12px; text-decoration: none;
      border-radius: 4px; opacity: 0; pointer-events: none;
      transition: all 0.2s; z-index: 10000;
    }
    .skip-to-content:focus { top: 6px; opacity: 1; pointer-events: auto; }

    /* ===== Layout ===== */
    .page {
      max-width: 1200px;
      margin: 0 auto;
      padding: 28px 22px 32px;
    }
    header.hero {
      display: grid;
      grid-template-columns: 1.3fr 1fr;
      gap: 16px;
      align-items: end;
      margin-bottom: 16px;
    }
    .title-block h1 { font-size: 28px; margin-bottom: 8px; }
    .title-block p { font-size: 14px; color: var(--text-secondary); max-width: 68ch; }

    .legend-card {
      display: grid;
      grid-template-columns: 1fr;
      gap: 10px;
      justify-items: start;
    }
    .legend-title { font-size: 13px; color: var(--text-secondary); }
    .legend-row { display: flex; gap: 10px; flex-wrap: wrap; }
    .pill {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      padding: 8px 10px;
      border: 1px solid var(--border);
      border-radius: 999px;
      background: rgba(255,255,255,0.02);
      font-size: 12px;
      color: var(--text);
    }
    .swatch {
      width: 10px; height: 10px; border-radius: 999px;
      background: var(--accent);
      box-shadow: 0 0 0 2px rgba(255,255,255,0.06);
    }

    .content {
      display: grid;
      grid-template-columns: 1fr;
      gap: 14px;
    }

    .chart-wrap {
      padding: 18px 18px 14px;
    }

    .chart-header {
      display: flex;
      align-items: baseline;
      justify-content: space-between;
      gap: 12px;
      margin-bottom: 8px;
    }
    .chart-header h2 { font-size: 16px; }
    .chart-header .meta { font-size: 12px; color: var(--text-secondary); }

    .controls {
      display: flex;
      flex-wrap: wrap;
      gap: 10px 14px;
      margin: 10px 0 0;
      align-items: center;
    }
    .control {
      display: inline-flex;
      gap: 10px;
      align-items: center;
      padding: 8px 10px;
      border: 1px solid var(--border);
      border-radius: 10px;
      background: rgba(255,255,255,0.02);
    }
    .control label { font-size: 12px; color: var(--text-secondary); }
    .control select {
      background: transparent;
      color: var(--text);
      border: none;
      outline: none;
      font-size: 12px;
      padding: 0;
      appearance: none;
    }

    .note {
      font-size: 12px;
      color: var(--text-secondary);
      margin-top: 10px;
    }

    /* ===== Parallel coordinates ===== */
    #pcSvg {
      width: 100%;
      height: 560px;
      display: block;
    }

    .axis path, .axis line {
      stroke: rgba(255,255,255,0.14);
      stroke-width: 1;
      shape-rendering: crispEdges;
    }
    .axis text {
      fill: var(--text-secondary);
      font-size: 11px;
    }

    .axis-label {
      fill: var(--text);
      font-size: 12px;
      font-weight: 600;
    }

    .line {
      fill: none;
      stroke-width: 1.6;
      opacity: 0.28;
      vector-effect: non-scaling-stroke;
    }

    .line.highlight {
      opacity: 0.95;
      stroke-width: 2.6;
      filter: drop-shadow(0 2px 6px rgba(0,0,0,0.35));
    }

    .line.dim {
      opacity: 0.08;
    }

    .crossings {
      font-size: 12px;
      color: var(--text-secondary);
    }

    .tooltip {
      position: fixed;
      pointer-events: none;
      opacity: 0;
      transform: translateY(-2px);
      transition: opacity 0.12s ease, transform 0.12s ease;
      background: rgba(20,20,20,0.92);
      border: 1px solid rgba(255,255,255,0.10);
      border-radius: 10px;
      padding: 10px 12px;
      min-width: 220px;
      max-width: 320px;
      box-shadow: 0 10px 30px rgba(0,0,0,0.35);
      z-index: 9997;
    }
    html.theme-light .tooltip {
      background: rgba(255,255,255,0.95);
      border-color: rgba(0,0,0,0.10);
      box-shadow: 0 10px 30px rgba(0,0,0,0.15);
    }
    .tooltip .t-title { font-size: 12px; font-weight: 650; color: var(--text); margin-bottom: 6px; }
    .tooltip .t-sub { font-size: 11px; color: var(--text-secondary); margin-bottom: 8px; }
    .tooltip .t-grid { display: grid; grid-template-columns: 1fr auto; gap: 4px 12px; }
    .tooltip .k { font-size: 11px; color: var(--text-secondary); }
    .tooltip .v { font-size: 11px; color: var(--text); font-variant-numeric: tabular-nums; }

    .divider {
      height: 1px;
      background: var(--border);
      margin: 10px 0;
    }

    @media (max-width: 920px) {
      header.hero { grid-template-columns: 1fr; }
      #pcSvg { height: 620px; }
    }
  </style>
</head>
<body>
  <a href="#main-content" class="skip-link" style="position:absolute;left:-9999px;top:auto;width:1px;height:1px;overflow:hidden;z-index:10000;padding:8px 16px;background:var(--accent);color:white;text-decoration:none;border-radius:4px;" onfocus="this.style.cssText='position:fixed;left:16px;top:16px;z-index:10000;padding:8px 16px;background:var(--accent);color:white;text-decoration:none;border-radius:4px;'" onblur="this.style.cssText='position:absolute;left:-9999px;top:auto;width:1px;height:1px;overflow:hidden;'">Skip to content</a>
  <main id="main-content">

  <div class="viz-menu">
    <button class="viz-menu-toggle" onclick="toggleMenu()" aria-label="Menu">
      <svg width="20" height="20" viewBox="0 0 20 20" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round">
        <line x1="3" y1="5" x2="17" y2="5"/><line x1="3" y1="10" x2="17" y2="10"/><line x1="3" y1="15" x2="17" y2="15"/>
      </svg>
    </button>
    <div class="viz-menu-dropdown" id="vizMenuDropdown">
      <button onclick="cycleTheme()"><span id="themeIcon">🌙</span><span id="themeLabel">Dark</span></button>
      <button onclick="downloadImage()"><span>📥</span><span>Download PNG</span></button>
      <button onclick="window.print()"><span>🖨️</span><span>Print / PDF</span></button>
    </div>
  </div>

  <a href="#main-content" class="skip-to-content">Skip to content</a>

  <main id="main-content" role="main">
    <section class="page">
      <header class="hero">
        <div class="title-block animate">
          <h1>National development profiles across seven indicators</h1>
          <p>
            Parallel coordinates encode 30 countries with seven axes. Each polyline is a country, colored by World Bank income group.
            Use hover to inspect outliers and crossings between adjacent dimensions.
          </p>
        </div>
        <aside class="card legend-card animate delay-1" aria-label="Legend">
          <div class="legend-title">Color = income group</div>
          <div class="legend-row" id="legendRow"></div>
          <div class="divider"></div>
          <div class="crossings" id="crossingsText">Computing strongest crossovers…</div>
        </aside>
      </header>

      <section class="card chart-wrap animate delay-2" aria-label="Parallel coordinates chart">
        <div class="chart-header">
          <h2>Parallel coordinates</h2>
          <div class="meta">Units: USD, index scores (0–1 / 0–100), tons, %</div>
        </div>

        <svg id="pcSvg" role="img" aria-label="Parallel coordinates plot of seven national development indicators"></svg>

        <div class="controls" aria-label="Chart controls">
          <div class="control">
            <label for="axisScale">Axis scaling</label>
            <select id="axisScale" onchange="setScaling(this.value)">
              <option value="z" selected>Z-score (within axis)</option>
              <option value="minmax">Min–max (within axis)</option>
              <option value="raw">Raw values</option>
            </select>
          </div>
          <div class="control">
            <label for="highlightGroup">Highlight</label>
            <select id="highlightGroup" onchange="setHighlight(this.value)">
              <option value="All" selected>All income groups</option>
              <option value="High">High</option>
              <option value="Upper-Middle">Upper-Middle</option>
              <option value="Lower-Middle">Lower-Middle</option>
              <option value="Low">Low</option>
            </select>
          </div>
        </div>

        <p class="note">
          Data: approximate 2023 estimates from World Bank/UNDP/Freedom House/Transparency International/IEA/SIPRI/ITU (see dataset notes).
        </p>
      </section>
    </section>
  </main>

  </main>

  <div class="tooltip" id="tooltip" role="dialog" aria-label="Country details"></div>

  <script>
    function toggleMenu() {
      var dropdown = document.getElementById('vizMenuDropdown') || document.getElementById('vizMenu');
      if (dropdown) dropdown.classList.toggle('open');
    }
    document.addEventListener('click', function(e) {
      if (!e.target.closest('.viz-menu')) {
        var dropdown = document.getElementById('vizMenuDropdown') || document.getElementById('vizMenu');
        if (dropdown) dropdown.classList.remove('open');
      }
    });
    document.addEventListener('keydown', function(e) {
      if (e.key === 'Escape') {
        var dropdown = document.getElementById('vizMenuDropdown') || document.getElementById('vizMenu');
        if (dropdown) dropdown.classList.remove('open');
      }
    });

    var savedTheme = localStorage.getItem('viz-theme');
    var currentTheme = savedTheme || (window.matchMedia('(prefers-color-scheme: light)').matches ? 'light' : 'dark');
    function applyTheme(t) {
      document.documentElement.className = 'theme-' + t;
      document.getElementById('themeIcon').textContent = t === 'dark' ? '🌙' : '☀️';
      document.getElementById('themeLabel').textContent = t === 'dark' ? 'Dark' : 'Light';
      localStorage.setItem('viz-theme', t);
      currentTheme = t;
      if (typeof onThemeChange === 'function') onThemeChange();
    }
    function cycleTheme() { applyTheme(currentTheme === 'dark' ? 'light' : 'dark'); }
    applyTheme(currentTheme);

    async function downloadImage() {
      var menu = document.querySelector('.viz-menu');
      menu.style.display = 'none';
      try {
        var url = await htmlToImage.toPng(document.body, {
          quality: 1,
          pixelRatio: 2,
          filter: function(n) { return !n.classList || !n.classList.contains('viz-menu'); }
        });
        var a = document.createElement('a');
        a.href = url;
        a.download = document.title.replace(/\s+/g, '-').toLowerCase() + '.png';
        a.click();
      } catch(e) {
        console.error('Download failed:', e);
      }
      menu.style.display = '';
    }

    var incomeColors = {
      'High': '#60a5fa',
      'Upper-Middle': '#34d399',
      'Lower-Middle': '#f59e0b',
      'Low': '#f87171'
    };

    var dimensions = [
      { key: 'gdp_per_capita_usd', label: 'GDP per capita', unit: 'USD', fmt: function(v){ return '$' + Math.round(v).toLocaleString(); } },
      { key: 'hdi', label: 'HDI', unit: 'index', fmt: function(v){ return v.toFixed(3); } },
      { key: 'freedom_index', label: 'Freedom Index', unit: 'score (0–100)', fmt: function(v){ return Math.round(v).toString(); } },
      { key: 'corruption_perceptions_index', label: 'Corruption Perceptions', unit: 'CPI (0–100)', fmt: function(v){ return Math.round(v).toString(); } },
      { key: 'co2_emissions_per_capita_tons', label: 'CO₂ per capita', unit: 'tons', fmt: function(v){ return v.toFixed(1) + ' t'; } },
      { key: 'military_expenditure_pct_gdp', label: 'Military exp.', unit: '% GDP', fmt: function(v){ return v.toFixed(1) + '%'; } },
      { key: 'internet_penetration_pct', label: 'Internet use', unit: '%', fmt: function(v){ return Math.round(v) + '%'; } }
    ];

    var state = {
      scaling: 'z',
      highlight: 'All',
      data: []
    };

    function setScaling(v) {
      state.scaling = v;
      render();
    }
    function setHighlight(v) {
      state.highlight = v;
      render();
    }

    function isDark() { return document.documentElement.classList.contains('theme-dark'); }

    function computeStats(values) {
      var n = values.length;
      var mean = values.reduce(function(a,b){ return a+b; },0) / n;
      var variance = values.reduce(function(a,b){ var d=b-mean; return a + d*d; },0) / (n || 1);
      var sd = Math.sqrt(variance) || 1;
      var min = Math.min.apply(null, values);
      var max = Math.max.apply(null, values);
      return { mean: mean, sd: sd, min: min, max: max };
    }

    function normalize(value, stats, mode) {
      if (mode === 'raw') return value;
      if (mode === 'minmax') {
        var d = (stats.max - stats.min) || 1;
        return (value - stats.min) / d;
      }
      // z-score
      return (value - stats.mean) / stats.sd;
    }

    function buildLegend() {
      var legendRow = document.getElementById('legendRow');
      legendRow.innerHTML = '';
      ['High','Upper-Middle','Lower-Middle','Low'].forEach(function(g){
        var pill = document.createElement('div');
        pill.className = 'pill';
        var sw = document.createElement('span');
        sw.className = 'swatch';
        sw.style.background = incomeColors[g];
        var tx = document.createElement('span');
        tx.textContent = g;
        pill.appendChild(sw);
        pill.appendChild(tx);
        legendRow.appendChild(pill);
      });
    }

    function formatTick(dimKey, val, mode, stats) {
      if (mode === 'raw') {
        var dim = dimensions.find(function(d){ return d.key === dimKey; });
        return dim ? dim.fmt(val) : String(val);
      }
      if (mode === 'minmax') {
        // show raw endpoints only
        return '';
      }
      // z
      return val.toFixed(1);
    }

    function computeCrossovers(data, dims) {
      // For each adjacent pair, compute Spearman correlation; report weakest correlation pair (most crossings)
      function rank(arr) {
        var sorted = arr.map(function(v,i){ return {v:v,i:i}; }).sort(function(a,b){ return a.v - b.v; });
        var r = new Array(arr.length);
        for (var j=0;j<sorted.length;j++) r[sorted[j].i] = j+1;
        return r;
      }
      function spearman(a,b) {
        var ra=rank(a), rb=rank(b);
        var n=a.length;
        var num=0, da=0, db=0;
        var ma = (n+1)/2;
        var mb = ma;
        for (var i=0;i<n;i++) {
          var xa=ra[i]-ma; var xb=rb[i]-mb;
          num += xa*xb;
          da += xa*xa;
          db += xb*xb;
        }
        var den = Math.sqrt(da*db) || 1;
        return num/den;
      }
      var best = {pair: null, rho: 1};
      for (var k=0;k<dims.length-1;k++) {
        var d1=dims[k].key, d2=dims[k+1].key;
        var a=data.map(function(r){ return r[d1]; });
        var b=data.map(function(r){ return r[d2]; });
        var rho = spearman(a,b);
        if (Math.abs(rho) < Math.abs(best.rho)) best = {pair: [dims[k].label, dims[k+1].label], rho: rho};
      }
      return best;
    }

    function render() {
      if (!window.d3) { console.error('D3 not loaded'); return; }

      var svg = d3.select('#pcSvg');
      svg.selectAll('*').remove();

      var bb = document.getElementById('pcSvg').getBoundingClientRect();
      var width = Math.max(900, Math.round(bb.width));
      var height = Math.round(bb.height);
      svg.attr('viewBox', '0 0 ' + width + ' ' + height);

      var margin = { top: 44, right: 40, bottom: 34, left: 40 };
      var innerW = width - margin.left - margin.right;
      var innerH = height - margin.top - margin.bottom;

      var g = svg.append('g').attr('transform', 'translate(' + margin.left + ',' + margin.top + ')');

      var mode = state.scaling;
      var data = state.data.slice();

      // Stats per dimension
      var stats = {};
      dimensions.forEach(function(dim){
        stats[dim.key] = computeStats(data.map(function(d){ return +d[dim.key]; }));
      });

      // y scales
      var y = {};
      dimensions.forEach(function(dim) {
        if (mode === 'raw') {
          var s = stats[dim.key];
          y[dim.key] = d3.scaleLinear().domain([s.min, s.max]).range([innerH, 0]).nice();
        } else if (mode === 'minmax') {
          y[dim.key] = d3.scaleLinear().domain([0, 1]).range([innerH, 0]);
        } else {
          // z-score domain: clamp to [-3,3] based on observed
          var zs = data.map(function(d){ return normalize(+d[dim.key], stats[dim.key], 'z'); });
          var zmin = Math.min.apply(null, zs);
          var zmax = Math.max.apply(null, zs);
          var pad = 0.15;
          y[dim.key] = d3.scaleLinear().domain([zmin - pad, zmax + pad]).range([innerH, 0]).nice();
        }
      });

      var x = d3.scalePoint().domain(dimensions.map(function(d){ return d.key; })).range([0, innerW]).padding(0.5);

      function valueFor(d, key) {
        var v = +d[key];
        if (mode === 'raw') return v;
        if (mode === 'minmax') return normalize(v, stats[key], 'minmax');
        return normalize(v, stats[key], 'z');
      }

      function path(d) {
        return d3.line()(dimensions.map(function(p) { return [x(p.key), y[p.key](valueFor(d, p.key))]; }));
      }

      // Grid/axes
      var axisG = g.selectAll('.axis').data(dimensions).enter().append('g')
        .attr('class', 'axis')
        .attr('transform', function(d) { return 'translate(' + x(d.key) + ',0)'; });

      axisG.each(function(dim) {
        var ax;
        if (mode === 'minmax') {
          ax = d3.axisLeft(y[dim.key]).ticks(5);
        } else {
          ax = d3.axisLeft(y[dim.key]).ticks(5);
        }
        d3.select(this).call(ax);
      });

      // Axis labels + units
      axisG.append('text')
        .attr('class', 'axis-label')
        .attr('text-anchor', 'middle')
        .attr('y', -18)
        .text(function(d) { return dimensions.find(function(xd){ return xd.key===d.key; }).label; });

      axisG.append('text')
        .attr('text-anchor', 'middle')
        .attr('y', -2)
        .attr('fill', 'var(--text-secondary)')
        .attr('font-size', 10)
        .text(function(d) {
          var dim = dimensions.find(function(xd){ return xd.key===d.key; });
          return mode === 'raw' ? dim.unit : (mode === 'minmax' ? '0–1' : 'z');
        });

      // Overlay subtle band to help track crossings
      g.append('rect')
        .attr('x', 0)
        .attr('y', 0)
        .attr('width', innerW)
        .attr('height', innerH)
        .attr('fill', 'transparent');

      // Lines
      var highlightGroup = state.highlight;
      var showAll = highlightGroup === 'All';

      var lines = g.append('g').attr('aria-label', 'Country polylines');

      var tooltip = document.getElementById('tooltip');

      function showTooltip(ev, d) {
        var linesHtml = '';
        dimensions.forEach(function(dim) {
          linesHtml += '<div class="k">' + dim.label + '</div><div class="v">' + (dim.fmt(+d[dim.key])) + '</div>';
        });
        tooltip.innerHTML =
          '<div class="t-title">' + d.country + '</div>' +
          '<div class="t-sub">Income group: <span style="color:' + incomeColors[d.income_group] + '">' + d.income_group + '</span></div>' +
          '<div class="t-grid">' + linesHtml + '</div>';
        tooltip.style.opacity = '1';
        tooltip.style.transform = 'translateY(0)';
        positionTooltip(ev);
      }

      function positionTooltip(ev) {
        var pad = 14;
        var x = ev.clientX + pad;
        var y = ev.clientY + pad;
        var rect = tooltip.getBoundingClientRect();
        if (x + rect.width + pad > window.innerWidth) x = ev.clientX - rect.width - pad;
        if (y + rect.height + pad > window.innerHeight) y = ev.clientY - rect.height - pad;
        tooltip.style.left = Math.max(10, x) + 'px';
        tooltip.style.top = Math.max(10, y) + 'px';
      }

      function hideTooltip() {
        tooltip.style.opacity = '0';
        tooltip.style.transform = 'translateY(-2px)';
      }

      var lineSel = lines.selectAll('path')
        .data(data)
        .enter()
        .append('path')
        .attr('class', 'line')
        .attr('d', path)
        .attr('stroke', function(d) { return incomeColors[d.income_group] || '#94a3b8'; })
        .attr('tabindex', 0)
        .attr('role', 'img')
        .attr('aria-label', function(d){ return 'Country profile: ' + d.country + ', income group ' + d.income_group; })
        .on('mouseenter', function(ev, d) {
          lineSel.classed('dim', true).classed('highlight', false);
          d3.select(this).classed('dim', false).classed('highlight', true);
          showTooltip(ev, d);
        })
        .on('mousemove', function(ev) { positionTooltip(ev); })
        .on('mouseleave', function() {
          hideTooltip();
          applyHighlight();
        })
        .on('focus', function(ev, d) {
          lineSel.classed('dim', true).classed('highlight', false);
          d3.select(this).classed('dim', false).classed('highlight', true);
          showTooltip(ev, d);
        })
        .on('blur', function() {
          hideTooltip();
          applyHighlight();
        });

      function applyHighlight() {
        if (showAll) {
          lineSel.classed('dim', false).classed('highlight', false);
          lineSel.style('opacity', 0.28);
          return;
        }
        lineSel.classed('highlight', false);
        lineSel.classed('dim', function(d){ return d.income_group !== highlightGroup; });
        lineSel.style('opacity', function(d){ return d.income_group === highlightGroup ? 0.52 : null; });
      }

      applyHighlight();

      // Crossovers summary
      var cross = computeCrossovers(state.data, dimensions);
      var txt = 'Strongest crossings (weakest rank alignment): ' + cross.pair[0] + ' → ' + cross.pair[1] + ' (Spearman ρ ≈ ' + cross.rho.toFixed(2) + ')';
      document.getElementById('crossingsText').textContent = txt;

      // Extra: emphasize Freedom↔Corruption pairing per goal
      var freedomIdx = dimensions.findIndex(function(d){ return d.key === 'freedom_index'; });
      var cpiIdx = dimensions.findIndex(function(d){ return d.key === 'corruption_perceptions_index'; });
