          .attr('stroke', isDark() ? 'rgba(59,130,246,0.10)' : 'rgba(37,99,235,0.10)')
          .attr('stroke-width', 1)
          .lower();
      }

      // Foreground axis lines on top of highlight band
      axisG.raise();
      lines.raise();
    }

    function onThemeChange() {
      render();
    }

    async function loadData() {
      try {
        var res = await fetch('/app/benchmark/source_data.json');
        var json = await res.json();
        state.data = json.national_development.data;
        buildLegend();
        render();
      } catch(e) {
        console.error('Failed to load data:', e);
        document.getElementById('crossingsText').textContent = 'Failed to load data.';
      }
    }

    window.addEventListener('load', loadData);
